window.MG_LAZY_DATA["data/lazy/owner-courses/a003-277aada21d34e787.json"]={sha256:"277aada21d34e787cdc015b4dd8097a5425a6963ab633bb6ea6709d294392559",value:{"id":"a003","title":"矽晶圓線鋸切片","titleEn":"Silicon wafer wire sawing","category":"semiconductor","kind":"course","summary":"以 4 階段、24 個工程工作包拆解切縫、TTV、次表面損傷，完成圖解、對照、敏感度分析、故障判別、量測規劃與驗收。","summaryEn":"Four stages and 24 work packages explore kerf, ttv and subsurface damage through diagrams, comparisons, sensitivity studies, fault diagnosis, measurement plans and acceptance reviews.","sourceIds":["v8a-sumco","v8a-wafer","v3-media-80679a241086"],"status":"guided","contentStatus":"reviewable-educational-curriculum","curriculumVersion":8,"depth":4,"stepCount":24,"estimatedMinutes":720,"simulationOnly":true,"languageCoverage":["zh-TW","en"],"scope":"依公開原理編寫的雙語概念實作課；每步交付可審查的工程證據。24 步是學習拆解，不代表晶圓廠的完整配方。自行設定的數值須標為假設。題目不含可直接操作的化學混配、設備設定或量產公差；照片與外部影片為代表媒體，不是假稱每步實拍。","scopeEn":"Bilingual conceptual exercises based on public principles, with reviewable evidence at each step. The 24 steps are a learning decomposition, not a complete fab recipe. Chosen numerical inputs must be labeled hypothetical. No directly operable chemical mixtures, equipment settings or production tolerances are supplied. Photos and external videos are representative media, not claimed as recordings of every step.","diagram":{"type":"wafer","labels":["晶棒與切片預算","線網與切削互動","片形與損傷證據","良率與後段交接"],"labelsEn":["Ingot and slicing budget","Wire web and cutting","Geometry and damage","Yield and downstream handoff"],"original":true,"notToScale":true},"stages":[{"id":"a003-stage01","order":1,"title":"晶棒與切片預算","titleEn":"Ingot and slicing budget","description":"在「晶棒與切片預算」建立六項互補證據，逐一檢查材料、幾何、物理機制與適用限制。","descriptionEn":"Build six complementary evidence items for ingot and slicing budget, checking materials, geometry, mechanisms and validity limits.","steps":[{"id":"a003-v8-01","order":1,"sequence":1,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-sumco","v8a-wafer"],"prerequisiteIds":[],"title":"辨識晶向","titleEn":"Identify crystal orientation","objective":"完成「辨識晶向」的因果圖，把切縫、TTV、次表面損傷中的相關限制連到可觀察證據。","objectiveEn":"Complete a causal diagram for identify crystal orientation, connecting relevant limits in kerf, ttv and subsurface damage to observable evidence.","instruction":"本步問題：辨識晶向。畫一張含作用前後狀態的原創圖；以箭頭標出本步原理中的因果關係；圈出一項仍需量測的未知量。判讀依據：晶向標記要連到晶棒座標，不能以外觀代替繞射證據。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Identify crystal orientation. Draw an original before/after diagram; mark the causal relationship in this step; circle one quantity still requiring measurement. Interpretation: Orientation marks require ingot coordinates and diffraction evidence, not appearance. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「晶向標記要連到晶棒座標，不能以外觀代替繞射證據。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Orientation marks require ingot coordinates and diffraction evidence, not appearance. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：TTV 與表面粗糙度可以互換。 應回到「辨識晶向」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: TTV and surface roughness are interchangeable. Revisit assumptions and sampling for identify crystal orientation and add discriminating evidence.","check":"交付「辨識晶向」因果圖：圖中要有邊界、輸入、輸出與一項不能僅由圖決定的量。","checkEn":"Submit the causal diagram for identify crystal orientation: Show boundaries, inputs, outputs and one quantity that the diagram alone cannot determine.","knowledge":[{"id":"a003-v8-01-k1","title":"辨識晶向的原理","titleEn":"Identify crystal orientation principle","text":"晶向標記要連到晶棒座標，不能以外觀代替繞射證據。","textEn":"Orientation marks require ingot coordinates and diffraction evidence, not appearance."},{"id":"a003-v8-01-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"可用片數的理想上限為可用長度除以每片厚度加切縫，實際還須扣除端損及不良片。","textEn":"Ideal slice count divides usable length by thickness plus kerf; real yield additionally loses end material and rejects."}],"quiz":{"question":"評估「辨識晶向」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating identify crystal orientation?","options":["晶向標記要連到晶棒座標，不能以外觀代替繞射證據。","TTV 與表面粗糙度可以互換。","只量中心厚度即可代表全片形貌。"],"optionsEn":["Orientation marks require ingot coordinates and diffraction evidence, not appearance.","TTV and surface roughness are interchangeable.","Center thickness alone represents full-wafer geometry."],"answer":0,"explanation":"晶向標記要連到晶棒座標，不能以外觀代替繞射證據。 可用片數的理想上限為可用長度除以每片厚度加切縫，實際還須扣除端損及不良片。","explanationEn":"Orientation marks require ingot coordinates and diffraction evidence, not appearance. Ideal slice count divides usable length by thickness plus kerf; real yield additionally loses end material and rejects."}},{"id":"a003-v8-02","order":2,"sequence":2,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-sumco","v8a-wafer"],"prerequisiteIds":["a003-v8-01"],"title":"定義可用晶棒長","titleEn":"Define usable ingot length","objective":"完成「定義可用晶棒長」的對照表，把切縫、TTV、次表面損傷中的相關限制連到可觀察證據。","objectiveEn":"Complete a controlled comparison for define usable ingot length, connecting relevant limits in kerf, ttv and subsurface damage to observable evidence.","instruction":"本步問題：定義可用晶棒長。建立兩個只改一項條件的假想案例；分開記錄可觀察差異與推測原因；說明如何用本步原理區分兩者。判讀依據：頭尾排除長度會改變可用片數。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Define usable ingot length. Create two hypothetical cases differing in one condition; separate observations from proposed causes; use this step’s principle to distinguish them. Interpretation: Head and tail exclusions change usable wafer count. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「頭尾排除長度會改變可用片數。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Head and tail exclusions change usable wafer count. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：TTV 與表面粗糙度可以互換。 應回到「定義可用晶棒長」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: TTV and surface roughness are interchangeable. Revisit assumptions and sampling for define usable ingot length and add discriminating evidence.","check":"交付「定義可用晶棒長」對照表：交出兩案例、固定條件、預期差異及一項可能混淆因素。","checkEn":"Submit the controlled comparison for define usable ingot length: Submit both cases, fixed conditions, predicted difference and one confounder.","knowledge":[{"id":"a003-v8-02-k1","title":"定義可用晶棒長的原理","titleEn":"Define usable ingot length principle","text":"頭尾排除長度會改變可用片數。","textEn":"Head and tail exclusions change usable wafer count."},{"id":"a003-v8-02-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"可用片數的理想上限為可用長度除以每片厚度加切縫，實際還須扣除端損及不良片。","textEn":"Ideal slice count divides usable length by thickness plus kerf; real yield additionally loses end material and rejects."}],"quiz":{"question":"評估「定義可用晶棒長」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating define usable ingot length?","options":["TTV 與表面粗糙度可以互換。","頭尾排除長度會改變可用片數。","只量中心厚度即可代表全片形貌。"],"optionsEn":["TTV and surface roughness are interchangeable.","Head and tail exclusions change usable wafer count.","Center thickness alone represents full-wafer geometry."],"answer":1,"explanation":"頭尾排除長度會改變可用片數。 可用片數的理想上限為可用長度除以每片厚度加切縫，實際還須扣除端損及不良片。","explanationEn":"Head and tail exclusions change usable wafer count. Ideal slice count divides usable length by thickness plus kerf; real yield additionally loses end material and rejects."}},{"id":"a003-v8-03","order":3,"sequence":3,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-sumco","v8a-wafer"],"prerequisiteIds":["a003-v8-02"],"title":"切縫預算","titleEn":"Budget kerf","objective":"完成「切縫預算」的敏感度草圖，把切縫、TTV、次表面損傷中的相關限制連到可觀察證據。","objectiveEn":"Complete a sensitivity sketch for budget kerf, connecting relevant limits in kerf, ttv and subsurface damage to observable evidence.","instruction":"本步問題：切縫預算。選出本步的一項輸入及一項輸出；以自訂低、中、高三點畫趨勢；逐點標註假設，並寫出趨勢可能失效的條件。判讀依據：每片占用長度包含晶圓厚度與切縫。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。 自訂算例：可用晶棒長 100 mm、切片厚 0.8 mm、切縫 0.2 mm；先求理想片數，再將切縫改為 0.25 mm 比較整數片數，列出尚未納入的端損與不良片。","instructionEn":"Question for this step: Budget kerf. Select one input and output for this step; sketch a hypothetical low/mid/high trend; label assumptions and state when the trend may fail. Interpretation: Length consumed per slice includes wafer thickness and kerf. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs. Hypothetical exercise: usable ingot length 100 mm, slice thickness 0.8 mm and kerf 0.2 mm. Calculate ideal integer count, change kerf to 0.25 mm and list excluded end losses and rejects.","observation":"檢查結果是否能支持「每片占用長度包含晶圓厚度與切縫。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Length consumed per slice includes wafer thickness and kerf. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：TTV 與表面粗糙度可以互換。 應回到「切縫預算」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: TTV and surface roughness are interchangeable. Revisit assumptions and sampling for budget kerf and add discriminating evidence.","check":"交付「切縫預算」敏感度草圖：圖須有變數、單位或無因次定義、三個假設點及適用範圍。 同時交付算例的中間步驟或比較圖，並標示假設與模型限制。","checkEn":"Submit the sensitivity sketch for budget kerf: Include variables, units or dimensionless definitions, three hypothetical points and validity limits. Also submit intermediate calculations or comparison diagrams with assumptions and model limits.","knowledge":[{"id":"a003-v8-03-k1","title":"切縫預算的原理","titleEn":"Budget kerf principle","text":"每片占用長度包含晶圓厚度與切縫。","textEn":"Length consumed per slice includes wafer thickness and kerf."},{"id":"a003-v8-03-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"可用片數的理想上限為可用長度除以每片厚度加切縫，實際還須扣除端損及不良片。","textEn":"Ideal slice count divides usable length by thickness plus kerf; real yield additionally loses end material and rejects."}],"quiz":{"question":"評估「切縫預算」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating budget kerf?","options":["TTV 與表面粗糙度可以互換。","只量中心厚度即可代表全片形貌。","每片占用長度包含晶圓厚度與切縫。"],"optionsEn":["TTV and surface roughness are interchangeable.","Center thickness alone represents full-wafer geometry.","Length consumed per slice includes wafer thickness and kerf."],"answer":2,"explanation":"每片占用長度包含晶圓厚度與切縫。 可用片數的理想上限為可用長度除以每片厚度加切縫，實際還須扣除端損及不良片。","explanationEn":"Length consumed per slice includes wafer thickness and kerf. Ideal slice count divides usable length by thickness plus kerf; real yield additionally loses end material and rejects."}},{"id":"a003-v8-04","order":4,"sequence":4,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-sumco","v8a-wafer"],"prerequisiteIds":["a003-v8-03"],"title":"厚度留量","titleEn":"Reserve thickness allowance","objective":"完成「厚度留量」的故障判別表，把切縫、TTV、次表面損傷中的相關限制連到可觀察證據。","objectiveEn":"Complete a fault-discrimination table for reserve thickness allowance, connecting relevant limits in kerf, ttv and subsurface damage to observable evidence.","instruction":"本步問題：厚度留量。假設本步預期結果未出現；提出兩個不同機制；為各機制選一個能支持或否定的觀察，避免只重複同一量測。判讀依據：切片厚度還須支付損傷移除與拋光留量。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Reserve thickness allowance. Assume the expected result fails; propose two distinct mechanisms; choose an observation that supports or rejects each rather than repeating one measurement. Interpretation: Sliced thickness must cover damage removal and polishing allowance. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「切片厚度還須支付損傷移除與拋光留量。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Sliced thickness must cover damage removal and polishing allowance. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：TTV 與表面粗糙度可以互換。 應回到「厚度留量」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: TTV and surface roughness are interchangeable. Revisit assumptions and sampling for reserve thickness allowance and add discriminating evidence.","check":"交付「厚度留量」故障判別表：至少列出兩個假說、各自的辨別證據及先檢查順序。","checkEn":"Submit the fault-discrimination table for reserve thickness allowance: List two hypotheses, discriminating evidence for each and a check order.","knowledge":[{"id":"a003-v8-04-k1","title":"厚度留量的原理","titleEn":"Reserve thickness allowance principle","text":"切片厚度還須支付損傷移除與拋光留量。","textEn":"Sliced thickness must cover damage removal and polishing allowance."},{"id":"a003-v8-04-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"可用片數的理想上限為可用長度除以每片厚度加切縫，實際還須扣除端損及不良片。","textEn":"Ideal slice count divides usable length by thickness plus kerf; real yield additionally loses end material and rejects."}],"quiz":{"question":"評估「厚度留量」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating reserve thickness allowance?","options":["切片厚度還須支付損傷移除與拋光留量。","TTV 與表面粗糙度可以互換。","只量中心厚度即可代表全片形貌。"],"optionsEn":["Sliced thickness must cover damage removal and polishing allowance.","TTV and surface roughness are interchangeable.","Center thickness alone represents full-wafer geometry."],"answer":0,"explanation":"切片厚度還須支付損傷移除與拋光留量。 可用片數的理想上限為可用長度除以每片厚度加切縫，實際還須扣除端損及不良片。","explanationEn":"Sliced thickness must cover damage removal and polishing allowance. Ideal slice count divides usable length by thickness plus kerf; real yield additionally loses end material and rejects."}},{"id":"a003-v8-05","order":5,"sequence":5,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-sumco","v8a-wafer"],"prerequisiteIds":["a003-v8-04"],"title":"固定端受力圖","titleEn":"Draw mounting loads","objective":"完成「固定端受力圖」的量測規劃，把切縫、TTV、次表面損傷中的相關限制連到可觀察證據。","objectiveEn":"Complete a measurement plan for draw mounting loads, connecting relevant limits in kerf, ttv and subsurface damage to observable evidence.","instruction":"本步問題：固定端受力圖。針對本步定義待測量及採樣位置；列出解析度、背景與重複性；設計一個見證或空白，並說明檢出限如何限制結論。判讀依據：偏心固定會讓進給負荷在切片中不均。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Draw mounting loads. Define the measurand and sampling locations; list resolution, background and repeatability; design a witness or blank and explain detection-limit constraints. Interpretation: Eccentric mounting makes feed loading asymmetric. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「偏心固定會讓進給負荷在切片中不均。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Eccentric mounting makes feed loading asymmetric. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：TTV 與表面粗糙度可以互換。 應回到「固定端受力圖」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: TTV and surface roughness are interchangeable. Revisit assumptions and sampling for draw mounting loads and add discriminating evidence.","check":"交付「固定端受力圖」量測規劃：提供採樣座標、量測單位、對照與不確定度來源。","checkEn":"Submit the measurement plan for draw mounting loads: Provide sampling coordinates, units, controls and uncertainty sources.","knowledge":[{"id":"a003-v8-05-k1","title":"固定端受力圖的原理","titleEn":"Draw mounting loads principle","text":"偏心固定會讓進給負荷在切片中不均。","textEn":"Eccentric mounting makes feed loading asymmetric."},{"id":"a003-v8-05-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"可用片數的理想上限為可用長度除以每片厚度加切縫，實際還須扣除端損及不良片。","textEn":"Ideal slice count divides usable length by thickness plus kerf; real yield additionally loses end material and rejects."}],"quiz":{"question":"評估「固定端受力圖」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating draw mounting loads?","options":["TTV 與表面粗糙度可以互換。","偏心固定會讓進給負荷在切片中不均。","只量中心厚度即可代表全片形貌。"],"optionsEn":["TTV and surface roughness are interchangeable.","Eccentric mounting makes feed loading asymmetric.","Center thickness alone represents full-wafer geometry."],"answer":1,"explanation":"偏心固定會讓進給負荷在切片中不均。 可用片數的理想上限為可用長度除以每片厚度加切縫，實際還須扣除端損及不良片。","explanationEn":"Eccentric mounting makes feed loading asymmetric. Ideal slice count divides usable length by thickness plus kerf; real yield additionally loses end material and rejects."}},{"id":"a003-v8-06","order":6,"sequence":6,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-sumco","v8a-wafer"],"prerequisiteIds":["a003-v8-05"],"title":"來料電阻率分區","titleEn":"Map incoming resistivity","objective":"完成「來料電阻率分區」的工程驗收單，把切縫、TTV、次表面損傷中的相關限制連到可觀察證據。","objectiveEn":"Complete a engineering acceptance sheet for map incoming resistivity, connecting relevant limits in kerf, ttv and subsurface damage to observable evidence.","instruction":"本步問題：來料電阻率分區。整合本步及本階段先前證據；提出兩項彼此不同的接受條件；再列一個會讓你暫緩放行的結果及下一個確認動作。判讀依據：沿晶棒的電阻率變化不能用單片平均值代表。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Map incoming resistivity. Combine this step with earlier stage evidence; propose two independent acceptance criteria; name one hold condition and the next confirming action. Interpretation: One wafer average cannot describe axial resistivity variation. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「沿晶棒的電阻率變化不能用單片平均值代表。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: One wafer average cannot describe axial resistivity variation. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：TTV 與表面粗糙度可以互換。 應回到「來料電阻率分區」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: TTV and surface roughness are interchangeable. Revisit assumptions and sampling for map incoming resistivity and add discriminating evidence.","check":"交付「來料電阻率分區」工程驗收單：驗收單需有原理、兩項證據、保留疑問及前後模組交接。","checkEn":"Submit the engineering acceptance sheet for map incoming resistivity: The sheet needs the principle, two evidence items, open questions and module handoff.","knowledge":[{"id":"a003-v8-06-k1","title":"來料電阻率分區的原理","titleEn":"Map incoming resistivity principle","text":"沿晶棒的電阻率變化不能用單片平均值代表。","textEn":"One wafer average cannot describe axial resistivity variation."},{"id":"a003-v8-06-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"可用片數的理想上限為可用長度除以每片厚度加切縫，實際還須扣除端損及不良片。","textEn":"Ideal slice count divides usable length by thickness plus kerf; real yield additionally loses end material and rejects."}],"quiz":{"question":"評估「來料電阻率分區」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating map incoming resistivity?","options":["TTV 與表面粗糙度可以互換。","只量中心厚度即可代表全片形貌。","沿晶棒的電阻率變化不能用單片平均值代表。"],"optionsEn":["TTV and surface roughness are interchangeable.","Center thickness alone represents full-wafer geometry.","One wafer average cannot describe axial resistivity variation."],"answer":2,"explanation":"沿晶棒的電阻率變化不能用單片平均值代表。 可用片數的理想上限為可用長度除以每片厚度加切縫，實際還須扣除端損及不良片。","explanationEn":"One wafer average cannot describe axial resistivity variation. Ideal slice count divides usable length by thickness plus kerf; real yield additionally loses end material and rejects."}}]},{"id":"a003-stage02","order":2,"title":"線網與切削互動","titleEn":"Wire web and cutting","description":"在「線網與切削互動」建立六項互補證據，逐一檢查材料、幾何、物理機制與適用限制。","descriptionEn":"Build six complementary evidence items for wire web and cutting, checking materials, geometry, mechanisms and validity limits.","steps":[{"id":"a003-v8-07","order":1,"sequence":7,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-sumco","v8a-wafer"],"prerequisiteIds":["a003-v8-06"],"title":"線徑與槽距","titleEn":"Separate wire diameter and pitch","objective":"完成「線徑與槽距」的因果圖，把切縫、TTV、次表面損傷中的相關限制連到可觀察證據。","objectiveEn":"Complete a causal diagram for separate wire diameter and pitch, connecting relevant limits in kerf, ttv and subsurface damage to observable evidence.","instruction":"本步問題：線徑與槽距。畫一張含作用前後狀態的原創圖；以箭頭標出本步原理中的因果關係；圈出一項仍需量測的未知量。判讀依據：線徑、切縫與導輪槽距是不同幾何量。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Separate wire diameter and pitch. Draw an original before/after diagram; mark the causal relationship in this step; circle one quantity still requiring measurement. Interpretation: Wire diameter, kerf and guide-groove pitch differ. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「線徑、切縫與導輪槽距是不同幾何量。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Wire diameter, kerf and guide-groove pitch differ. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：晶圓表面外觀平整就可排除次表面裂紋。 應回到「線徑與槽距」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: A flat-looking surface rules out subsurface cracks. Revisit assumptions and sampling for separate wire diameter and pitch and add discriminating evidence.","check":"交付「線徑與槽距」因果圖：圖中要有邊界、輸入、輸出與一項不能僅由圖決定的量。","checkEn":"Submit the causal diagram for separate wire diameter and pitch: Show boundaries, inputs, outputs and one quantity that the diagram alone cannot determine.","knowledge":[{"id":"a003-v8-07-k1","title":"線徑與槽距的原理","titleEn":"Separate wire diameter and pitch principle","text":"線徑、切縫與導輪槽距是不同幾何量。","textEn":"Wire diameter, kerf and guide-groove pitch differ."},{"id":"a003-v8-07-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"線網的機械耦合使單條線受力改變可能影響相鄰切面，進給穩定性需與導輪狀態一起看。","textEn":"Mechanical coupling in a wire web means one load change can affect neighboring cuts; inspect feed stability with guide condition."}],"quiz":{"question":"評估「線徑與槽距」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating separate wire diameter and pitch?","options":["線徑、切縫與導輪槽距是不同幾何量。","晶圓表面外觀平整就可排除次表面裂紋。","切片厚度就是最終成品厚度。"],"optionsEn":["Wire diameter, kerf and guide-groove pitch differ.","A flat-looking surface rules out subsurface cracks.","Sliced thickness equals final finished thickness."],"answer":0,"explanation":"線徑、切縫與導輪槽距是不同幾何量。 線網的機械耦合使單條線受力改變可能影響相鄰切面，進給穩定性需與導輪狀態一起看。","explanationEn":"Wire diameter, kerf and guide-groove pitch differ. Mechanical coupling in a wire web means one load change can affect neighboring cuts; inspect feed stability with guide condition."}},{"id":"a003-v8-08","order":2,"sequence":8,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-sumco","v8a-wafer"],"prerequisiteIds":["a003-v8-07"],"title":"張力與撓曲","titleEn":"Relate tension and deflection","objective":"完成「張力與撓曲」的對照表，把切縫、TTV、次表面損傷中的相關限制連到可觀察證據。","objectiveEn":"Complete a controlled comparison for relate tension and deflection, connecting relevant limits in kerf, ttv and subsurface damage to observable evidence.","instruction":"本步問題：張力與撓曲。建立兩個只改一項條件的假想案例；分開記錄可觀察差異與推測原因；說明如何用本步原理區分兩者。判讀依據：同一橫向負荷下張力改變線網撓曲。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Relate tension and deflection. Create two hypothetical cases differing in one condition; separate observations from proposed causes; use this step’s principle to distinguish them. Interpretation: Wire tension changes deflection under the same transverse load. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「同一橫向負荷下張力改變線網撓曲。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Wire tension changes deflection under the same transverse load. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：晶圓表面外觀平整就可排除次表面裂紋。 應回到「張力與撓曲」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: A flat-looking surface rules out subsurface cracks. Revisit assumptions and sampling for relate tension and deflection and add discriminating evidence.","check":"交付「張力與撓曲」對照表：交出兩案例、固定條件、預期差異及一項可能混淆因素。","checkEn":"Submit the controlled comparison for relate tension and deflection: Submit both cases, fixed conditions, predicted difference and one confounder.","knowledge":[{"id":"a003-v8-08-k1","title":"張力與撓曲的原理","titleEn":"Relate tension and deflection principle","text":"同一橫向負荷下張力改變線網撓曲。","textEn":"Wire tension changes deflection under the same transverse load."},{"id":"a003-v8-08-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"線網的機械耦合使單條線受力改變可能影響相鄰切面，進給穩定性需與導輪狀態一起看。","textEn":"Mechanical coupling in a wire web means one load change can affect neighboring cuts; inspect feed stability with guide condition."}],"quiz":{"question":"評估「張力與撓曲」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating relate tension and deflection?","options":["晶圓表面外觀平整就可排除次表面裂紋。","同一橫向負荷下張力改變線網撓曲。","切片厚度就是最終成品厚度。"],"optionsEn":["A flat-looking surface rules out subsurface cracks.","Wire tension changes deflection under the same transverse load.","Sliced thickness equals final finished thickness."],"answer":1,"explanation":"同一橫向負荷下張力改變線網撓曲。 線網的機械耦合使單條線受力改變可能影響相鄰切面，進給穩定性需與導輪狀態一起看。","explanationEn":"Wire tension changes deflection under the same transverse load. Mechanical coupling in a wire web means one load change can affect neighboring cuts; inspect feed stability with guide condition."}},{"id":"a003-v8-09","order":3,"sequence":9,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-sumco","v8a-wafer"],"prerequisiteIds":["a003-v8-08"],"title":"進給與線速分工","titleEn":"Separate feed and wire speed","objective":"完成「進給與線速分工」的敏感度草圖，把切縫、TTV、次表面損傷中的相關限制連到可觀察證據。","objectiveEn":"Complete a sensitivity sketch for separate feed and wire speed, connecting relevant limits in kerf, ttv and subsurface damage to observable evidence.","instruction":"本步問題：進給與線速分工。選出本步的一項輸入及一項輸出；以自訂低、中、高三點畫趨勢；逐點標註假設，並寫出趨勢可能失效的條件。判讀依據：進給速度決定進入速率，線速影響磨粒接觸歷程。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Separate feed and wire speed. Select one input and output for this step; sketch a hypothetical low/mid/high trend; label assumptions and state when the trend may fail. Interpretation: Feed controls penetration while wire speed changes abrasive contact history. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「進給速度決定進入速率，線速影響磨粒接觸歷程。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Feed controls penetration while wire speed changes abrasive contact history. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：晶圓表面外觀平整就可排除次表面裂紋。 應回到「進給與線速分工」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: A flat-looking surface rules out subsurface cracks. Revisit assumptions and sampling for separate feed and wire speed and add discriminating evidence.","check":"交付「進給與線速分工」敏感度草圖：圖須有變數、單位或無因次定義、三個假設點及適用範圍。","checkEn":"Submit the sensitivity sketch for separate feed and wire speed: Include variables, units or dimensionless definitions, three hypothetical points and validity limits.","knowledge":[{"id":"a003-v8-09-k1","title":"進給與線速分工的原理","titleEn":"Separate feed and wire speed principle","text":"進給速度決定進入速率，線速影響磨粒接觸歷程。","textEn":"Feed controls penetration while wire speed changes abrasive contact history."},{"id":"a003-v8-09-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"線網的機械耦合使單條線受力改變可能影響相鄰切面，進給穩定性需與導輪狀態一起看。","textEn":"Mechanical coupling in a wire web means one load change can affect neighboring cuts; inspect feed stability with guide condition."}],"quiz":{"question":"評估「進給與線速分工」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating separate feed and wire speed?","options":["晶圓表面外觀平整就可排除次表面裂紋。","切片厚度就是最終成品厚度。","進給速度決定進入速率，線速影響磨粒接觸歷程。"],"optionsEn":["A flat-looking surface rules out subsurface cracks.","Sliced thickness equals final finished thickness.","Feed controls penetration while wire speed changes abrasive contact history."],"answer":2,"explanation":"進給速度決定進入速率，線速影響磨粒接觸歷程。 線網的機械耦合使單條線受力改變可能影響相鄰切面，進給穩定性需與導輪狀態一起看。","explanationEn":"Feed controls penetration while wire speed changes abrasive contact history. Mechanical coupling in a wire web means one load change can affect neighboring cuts; inspect feed stability with guide condition."}},{"id":"a003-v8-10","order":4,"sequence":10,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-sumco","v8a-wafer"],"prerequisiteIds":["a003-v8-09"],"title":"磨粒分布","titleEn":"Inspect abrasive distribution","objective":"完成「磨粒分布」的故障判別表，把切縫、TTV、次表面損傷中的相關限制連到可觀察證據。","objectiveEn":"Complete a fault-discrimination table for inspect abrasive distribution, connecting relevant limits in kerf, ttv and subsurface damage to observable evidence.","instruction":"本步問題：磨粒分布。假設本步預期結果未出現；提出兩個不同機制；為各機制選一個能支持或否定的觀察，避免只重複同一量測。判讀依據：少數過大磨粒可能留下深損傷，平均粒徑不足以判讀。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Inspect abrasive distribution. Assume the expected result fails; propose two distinct mechanisms; choose an observation that supports or rejects each rather than repeating one measurement. Interpretation: Oversized abrasive tails can cause deep damage despite a stable mean size. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「少數過大磨粒可能留下深損傷，平均粒徑不足以判讀。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Oversized abrasive tails can cause deep damage despite a stable mean size. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：晶圓表面外觀平整就可排除次表面裂紋。 應回到「磨粒分布」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: A flat-looking surface rules out subsurface cracks. Revisit assumptions and sampling for inspect abrasive distribution and add discriminating evidence.","check":"交付「磨粒分布」故障判別表：至少列出兩個假說、各自的辨別證據及先檢查順序。","checkEn":"Submit the fault-discrimination table for inspect abrasive distribution: List two hypotheses, discriminating evidence for each and a check order.","knowledge":[{"id":"a003-v8-10-k1","title":"磨粒分布的原理","titleEn":"Inspect abrasive distribution principle","text":"少數過大磨粒可能留下深損傷，平均粒徑不足以判讀。","textEn":"Oversized abrasive tails can cause deep damage despite a stable mean size."},{"id":"a003-v8-10-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"線網的機械耦合使單條線受力改變可能影響相鄰切面，進給穩定性需與導輪狀態一起看。","textEn":"Mechanical coupling in a wire web means one load change can affect neighboring cuts; inspect feed stability with guide condition."}],"quiz":{"question":"評估「磨粒分布」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating inspect abrasive distribution?","options":["少數過大磨粒可能留下深損傷，平均粒徑不足以判讀。","晶圓表面外觀平整就可排除次表面裂紋。","切片厚度就是最終成品厚度。"],"optionsEn":["Oversized abrasive tails can cause deep damage despite a stable mean size.","A flat-looking surface rules out subsurface cracks.","Sliced thickness equals final finished thickness."],"answer":0,"explanation":"少數過大磨粒可能留下深損傷，平均粒徑不足以判讀。 線網的機械耦合使單條線受力改變可能影響相鄰切面，進給穩定性需與導輪狀態一起看。","explanationEn":"Oversized abrasive tails can cause deep damage despite a stable mean size. Mechanical coupling in a wire web means one load change can affect neighboring cuts; inspect feed stability with guide condition."}},{"id":"a003-v8-11","order":5,"sequence":11,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-sumco","v8a-wafer"],"prerequisiteIds":["a003-v8-10"],"title":"排屑路徑","titleEn":"Trace debris removal","objective":"完成「排屑路徑」的量測規劃，把切縫、TTV、次表面損傷中的相關限制連到可觀察證據。","objectiveEn":"Complete a measurement plan for trace debris removal, connecting relevant limits in kerf, ttv and subsurface damage to observable evidence.","instruction":"本步問題：排屑路徑。針對本步定義待測量及採樣位置；列出解析度、背景與重複性；設計一個見證或空白，並說明檢出限如何限制結論。判讀依據：排屑不足會改變接觸與局部熱負荷。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Trace debris removal. Define the measurand and sampling locations; list resolution, background and repeatability; design a witness or blank and explain detection-limit constraints. Interpretation: Poor debris removal changes contact and local heating. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「排屑不足會改變接觸與局部熱負荷。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Poor debris removal changes contact and local heating. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：晶圓表面外觀平整就可排除次表面裂紋。 應回到「排屑路徑」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: A flat-looking surface rules out subsurface cracks. Revisit assumptions and sampling for trace debris removal and add discriminating evidence.","check":"交付「排屑路徑」量測規劃：提供採樣座標、量測單位、對照與不確定度來源。","checkEn":"Submit the measurement plan for trace debris removal: Provide sampling coordinates, units, controls and uncertainty sources.","knowledge":[{"id":"a003-v8-11-k1","title":"排屑路徑的原理","titleEn":"Trace debris removal principle","text":"排屑不足會改變接觸與局部熱負荷。","textEn":"Poor debris removal changes contact and local heating."},{"id":"a003-v8-11-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"線網的機械耦合使單條線受力改變可能影響相鄰切面，進給穩定性需與導輪狀態一起看。","textEn":"Mechanical coupling in a wire web means one load change can affect neighboring cuts; inspect feed stability with guide condition."}],"quiz":{"question":"評估「排屑路徑」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating trace debris removal?","options":["晶圓表面外觀平整就可排除次表面裂紋。","排屑不足會改變接觸與局部熱負荷。","切片厚度就是最終成品厚度。"],"optionsEn":["A flat-looking surface rules out subsurface cracks.","Poor debris removal changes contact and local heating.","Sliced thickness equals final finished thickness."],"answer":1,"explanation":"排屑不足會改變接觸與局部熱負荷。 線網的機械耦合使單條線受力改變可能影響相鄰切面，進給穩定性需與導輪狀態一起看。","explanationEn":"Poor debris removal changes contact and local heating. Mechanical coupling in a wire web means one load change can affect neighboring cuts; inspect feed stability with guide condition."}},{"id":"a003-v8-12","order":6,"sequence":12,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-sumco","v8a-wafer"],"prerequisiteIds":["a003-v8-11"],"title":"斷線事件","titleEn":"Reconstruct wire breakage","objective":"完成「斷線事件」的工程驗收單，把切縫、TTV、次表面損傷中的相關限制連到可觀察證據。","objectiveEn":"Complete a engineering acceptance sheet for reconstruct wire breakage, connecting relevant limits in kerf, ttv and subsurface damage to observable evidence.","instruction":"本步問題：斷線事件。整合本步及本階段先前證據；提出兩項彼此不同的接受條件；再列一個會讓你暫緩放行的結果及下一個確認動作。判讀依據：斷線前的張力尖峰與片序能限定受影響區域。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Reconstruct wire breakage. Combine this step with earlier stage evidence; propose two independent acceptance criteria; name one hold condition and the next confirming action. Interpretation: Pre-break tension spikes and slice order delimit affected material. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「斷線前的張力尖峰與片序能限定受影響區域。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Pre-break tension spikes and slice order delimit affected material. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：晶圓表面外觀平整就可排除次表面裂紋。 應回到「斷線事件」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: A flat-looking surface rules out subsurface cracks. Revisit assumptions and sampling for reconstruct wire breakage and add discriminating evidence.","check":"交付「斷線事件」工程驗收單：驗收單需有原理、兩項證據、保留疑問及前後模組交接。","checkEn":"Submit the engineering acceptance sheet for reconstruct wire breakage: The sheet needs the principle, two evidence items, open questions and module handoff.","knowledge":[{"id":"a003-v8-12-k1","title":"斷線事件的原理","titleEn":"Reconstruct wire breakage principle","text":"斷線前的張力尖峰與片序能限定受影響區域。","textEn":"Pre-break tension spikes and slice order delimit affected material."},{"id":"a003-v8-12-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"線網的機械耦合使單條線受力改變可能影響相鄰切面，進給穩定性需與導輪狀態一起看。","textEn":"Mechanical coupling in a wire web means one load change can affect neighboring cuts; inspect feed stability with guide condition."}],"quiz":{"question":"評估「斷線事件」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating reconstruct wire breakage?","options":["晶圓表面外觀平整就可排除次表面裂紋。","切片厚度就是最終成品厚度。","斷線前的張力尖峰與片序能限定受影響區域。"],"optionsEn":["A flat-looking surface rules out subsurface cracks.","Sliced thickness equals final finished thickness.","Pre-break tension spikes and slice order delimit affected material."],"answer":2,"explanation":"斷線前的張力尖峰與片序能限定受影響區域。 線網的機械耦合使單條線受力改變可能影響相鄰切面，進給穩定性需與導輪狀態一起看。","explanationEn":"Pre-break tension spikes and slice order delimit affected material. Mechanical coupling in a wire web means one load change can affect neighboring cuts; inspect feed stability with guide condition."}}]},{"id":"a003-stage03","order":3,"title":"片形與損傷證據","titleEn":"Geometry and damage","description":"在「片形與損傷證據」建立六項互補證據，逐一檢查材料、幾何、物理機制與適用限制。","descriptionEn":"Build six complementary evidence items for geometry and damage, checking materials, geometry, mechanisms and validity limits.","steps":[{"id":"a003-v8-13","order":1,"sequence":13,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-sumco","v8a-wafer"],"prerequisiteIds":["a003-v8-12"],"title":"總厚度變異","titleEn":"Measure total thickness variation","objective":"完成「總厚度變異」的因果圖，把切縫、TTV、次表面損傷中的相關限制連到可觀察證據。","objectiveEn":"Complete a causal diagram for measure total thickness variation, connecting relevant limits in kerf, ttv and subsurface damage to observable evidence.","instruction":"本步問題：總厚度變異。畫一張含作用前後狀態的原創圖；以箭頭標出本步原理中的因果關係；圈出一項仍需量測的未知量。判讀依據：TTV 是厚度最大與最小之差，不是表面粗糙度。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Measure total thickness variation. Draw an original before/after diagram; mark the causal relationship in this step; circle one quantity still requiring measurement. Interpretation: TTV is maximum minus minimum thickness, not roughness. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「TTV 是厚度最大與最小之差，不是表面粗糙度。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: TTV is maximum minus minimum thickness, not roughness. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：平均值相同就不必檢查片間分布。 應回到「總厚度變異」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Equal averages eliminate the need to inspect wafer distributions. Revisit assumptions and sampling for measure total thickness variation and add discriminating evidence.","check":"交付「總厚度變異」因果圖：圖中要有邊界、輸入、輸出與一項不能僅由圖決定的量。","checkEn":"Submit the causal diagram for measure total thickness variation: Show boundaries, inputs, outputs and one quantity that the diagram alone cannot determine.","knowledge":[{"id":"a003-v8-13-k1","title":"總厚度變異的原理","titleEn":"Measure total thickness variation principle","text":"TTV 是厚度最大與最小之差，不是表面粗糙度。","textEn":"TTV is maximum minus minimum thickness, not roughness."},{"id":"a003-v8-13-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"TTV 用兩面的局部間距計算；弓形用中面相對參考面計算，因此厚度均勻的片仍可能彎曲。","textEn":"TTV measures local separation of both faces while bow describes the median surface; uniform thickness can coexist with curvature."}],"quiz":{"question":"評估「總厚度變異」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating measure total thickness variation?","options":["TTV 是厚度最大與最小之差，不是表面粗糙度。","平均值相同就不必檢查片間分布。","材料移除量不會影響可用晶圓數。"],"optionsEn":["TTV is maximum minus minimum thickness, not roughness.","Equal averages eliminate the need to inspect wafer distributions.","Material removal cannot affect usable wafer count."],"answer":0,"explanation":"TTV 是厚度最大與最小之差，不是表面粗糙度。 TTV 用兩面的局部間距計算；弓形用中面相對參考面計算，因此厚度均勻的片仍可能彎曲。","explanationEn":"TTV is maximum minus minimum thickness, not roughness. TTV measures local separation of both faces while bow describes the median surface; uniform thickness can coexist with curvature."}},{"id":"a003-v8-14","order":2,"sequence":14,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-sumco","v8a-wafer"],"prerequisiteIds":["a003-v8-13"],"title":"翹曲與弓形","titleEn":"Separate warp and bow","objective":"完成「翹曲與弓形」的對照表，把切縫、TTV、次表面損傷中的相關限制連到可觀察證據。","objectiveEn":"Complete a controlled comparison for separate warp and bow, connecting relevant limits in kerf, ttv and subsurface damage to observable evidence.","instruction":"本步問題：翹曲與弓形。建立兩個只改一項條件的假想案例；分開記錄可觀察差異與推測原因；說明如何用本步原理區分兩者。判讀依據：自由狀態形貌與夾持後平坦度不可混用。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Separate warp and bow. Create two hypothetical cases differing in one condition; separate observations from proposed causes; use this step’s principle to distinguish them. Interpretation: Free-state shape differs from clamped flatness. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「自由狀態形貌與夾持後平坦度不可混用。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Free-state shape differs from clamped flatness. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：平均值相同就不必檢查片間分布。 應回到「翹曲與弓形」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Equal averages eliminate the need to inspect wafer distributions. Revisit assumptions and sampling for separate warp and bow and add discriminating evidence.","check":"交付「翹曲與弓形」對照表：交出兩案例、固定條件、預期差異及一項可能混淆因素。","checkEn":"Submit the controlled comparison for separate warp and bow: Submit both cases, fixed conditions, predicted difference and one confounder.","knowledge":[{"id":"a003-v8-14-k1","title":"翹曲與弓形的原理","titleEn":"Separate warp and bow principle","text":"自由狀態形貌與夾持後平坦度不可混用。","textEn":"Free-state shape differs from clamped flatness."},{"id":"a003-v8-14-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"TTV 用兩面的局部間距計算；弓形用中面相對參考面計算，因此厚度均勻的片仍可能彎曲。","textEn":"TTV measures local separation of both faces while bow describes the median surface; uniform thickness can coexist with curvature."}],"quiz":{"question":"評估「翹曲與弓形」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating separate warp and bow?","options":["平均值相同就不必檢查片間分布。","自由狀態形貌與夾持後平坦度不可混用。","材料移除量不會影響可用晶圓數。"],"optionsEn":["Equal averages eliminate the need to inspect wafer distributions.","Free-state shape differs from clamped flatness.","Material removal cannot affect usable wafer count."],"answer":1,"explanation":"自由狀態形貌與夾持後平坦度不可混用。 TTV 用兩面的局部間距計算；弓形用中面相對參考面計算，因此厚度均勻的片仍可能彎曲。","explanationEn":"Free-state shape differs from clamped flatness. TTV measures local separation of both faces while bow describes the median surface; uniform thickness can coexist with curvature."}},{"id":"a003-v8-15","order":3,"sequence":15,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-sumco","v8a-wafer"],"prerequisiteIds":["a003-v8-14"],"title":"鋸痕方向","titleEn":"Register saw-mark direction","objective":"完成「鋸痕方向」的敏感度草圖，把切縫、TTV、次表面損傷中的相關限制連到可觀察證據。","objectiveEn":"Complete a sensitivity sketch for register saw-mark direction, connecting relevant limits in kerf, ttv and subsurface damage to observable evidence.","instruction":"本步問題：鋸痕方向。選出本步的一項輸入及一項輸出；以自訂低、中、高三點畫趨勢；逐點標註假設，並寫出趨勢可能失效的條件。判讀依據：鋸痕方向應與線運動及進給座標一起比較。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Register saw-mark direction. Select one input and output for this step; sketch a hypothetical low/mid/high trend; label assumptions and state when the trend may fail. Interpretation: Saw marks need registration to wire and feed directions. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「鋸痕方向應與線運動及進給座標一起比較。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Saw marks need registration to wire and feed directions. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：平均值相同就不必檢查片間分布。 應回到「鋸痕方向」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Equal averages eliminate the need to inspect wafer distributions. Revisit assumptions and sampling for register saw-mark direction and add discriminating evidence.","check":"交付「鋸痕方向」敏感度草圖：圖須有變數、單位或無因次定義、三個假設點及適用範圍。","checkEn":"Submit the sensitivity sketch for register saw-mark direction: Include variables, units or dimensionless definitions, three hypothetical points and validity limits.","knowledge":[{"id":"a003-v8-15-k1","title":"鋸痕方向的原理","titleEn":"Register saw-mark direction principle","text":"鋸痕方向應與線運動及進給座標一起比較。","textEn":"Saw marks need registration to wire and feed directions."},{"id":"a003-v8-15-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"TTV 用兩面的局部間距計算；弓形用中面相對參考面計算，因此厚度均勻的片仍可能彎曲。","textEn":"TTV measures local separation of both faces while bow describes the median surface; uniform thickness can coexist with curvature."}],"quiz":{"question":"評估「鋸痕方向」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating register saw-mark direction?","options":["平均值相同就不必檢查片間分布。","材料移除量不會影響可用晶圓數。","鋸痕方向應與線運動及進給座標一起比較。"],"optionsEn":["Equal averages eliminate the need to inspect wafer distributions.","Material removal cannot affect usable wafer count.","Saw marks need registration to wire and feed directions."],"answer":2,"explanation":"鋸痕方向應與線運動及進給座標一起比較。 TTV 用兩面的局部間距計算；弓形用中面相對參考面計算，因此厚度均勻的片仍可能彎曲。","explanationEn":"Saw marks need registration to wire and feed directions. TTV measures local separation of both faces while bow describes the median surface; uniform thickness can coexist with curvature."}},{"id":"a003-v8-16","order":4,"sequence":16,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-sumco","v8a-wafer"],"prerequisiteIds":["a003-v8-15"],"title":"次表面損傷","titleEn":"Estimate subsurface damage","objective":"完成「次表面損傷」的故障判別表，把切縫、TTV、次表面損傷中的相關限制連到可觀察證據。","objectiveEn":"Complete a fault-discrimination table for estimate subsurface damage, connecting relevant limits in kerf, ttv and subsurface damage to observable evidence.","instruction":"本步問題：次表面損傷。假設本步預期結果未出現；提出兩個不同機制；為各機制選一個能支持或否定的觀察，避免只重複同一量測。判讀依據：表面看似光滑仍可能保有次表面裂紋。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Estimate subsurface damage. Assume the expected result fails; propose two distinct mechanisms; choose an observation that supports or rejects each rather than repeating one measurement. Interpretation: An apparently smooth surface can retain subsurface cracks. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「表面看似光滑仍可能保有次表面裂紋。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: An apparently smooth surface can retain subsurface cracks. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：平均值相同就不必檢查片間分布。 應回到「次表面損傷」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Equal averages eliminate the need to inspect wafer distributions. Revisit assumptions and sampling for estimate subsurface damage and add discriminating evidence.","check":"交付「次表面損傷」故障判別表：至少列出兩個假說、各自的辨別證據及先檢查順序。","checkEn":"Submit the fault-discrimination table for estimate subsurface damage: List two hypotheses, discriminating evidence for each and a check order.","knowledge":[{"id":"a003-v8-16-k1","title":"次表面損傷的原理","titleEn":"Estimate subsurface damage principle","text":"表面看似光滑仍可能保有次表面裂紋。","textEn":"An apparently smooth surface can retain subsurface cracks."},{"id":"a003-v8-16-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"TTV 用兩面的局部間距計算；弓形用中面相對參考面計算，因此厚度均勻的片仍可能彎曲。","textEn":"TTV measures local separation of both faces while bow describes the median surface; uniform thickness can coexist with curvature."}],"quiz":{"question":"評估「次表面損傷」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating estimate subsurface damage?","options":["表面看似光滑仍可能保有次表面裂紋。","平均值相同就不必檢查片間分布。","材料移除量不會影響可用晶圓數。"],"optionsEn":["An apparently smooth surface can retain subsurface cracks.","Equal averages eliminate the need to inspect wafer distributions.","Material removal cannot affect usable wafer count."],"answer":0,"explanation":"表面看似光滑仍可能保有次表面裂紋。 TTV 用兩面的局部間距計算；弓形用中面相對參考面計算，因此厚度均勻的片仍可能彎曲。","explanationEn":"An apparently smooth surface can retain subsurface cracks. TTV measures local separation of both faces while bow describes the median surface; uniform thickness can coexist with curvature."}},{"id":"a003-v8-17","order":5,"sequence":17,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-sumco","v8a-wafer"],"prerequisiteIds":["a003-v8-16"],"title":"邊緣崩缺","titleEn":"Classify edge chips","objective":"完成「邊緣崩缺」的量測規劃，把切縫、TTV、次表面損傷中的相關限制連到可觀察證據。","objectiveEn":"Complete a measurement plan for classify edge chips, connecting relevant limits in kerf, ttv and subsurface damage to observable evidence.","instruction":"本步問題：邊緣崩缺。針對本步定義待測量及採樣位置；列出解析度、背景與重複性；設計一個見證或空白，並說明檢出限如何限制結論。判讀依據：邊緣缺口尺寸及位置共同影響後續破片風險。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Classify edge chips. Define the measurand and sampling locations; list resolution, background and repeatability; design a witness or blank and explain detection-limit constraints. Interpretation: Edge-chip size and position influence subsequent fracture risk. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「邊緣缺口尺寸及位置共同影響後續破片風險。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Edge-chip size and position influence subsequent fracture risk. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：平均值相同就不必檢查片間分布。 應回到「邊緣崩缺」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Equal averages eliminate the need to inspect wafer distributions. Revisit assumptions and sampling for classify edge chips and add discriminating evidence.","check":"交付「邊緣崩缺」量測規劃：提供採樣座標、量測單位、對照與不確定度來源。","checkEn":"Submit the measurement plan for classify edge chips: Provide sampling coordinates, units, controls and uncertainty sources.","knowledge":[{"id":"a003-v8-17-k1","title":"邊緣崩缺的原理","titleEn":"Classify edge chips principle","text":"邊緣缺口尺寸及位置共同影響後續破片風險。","textEn":"Edge-chip size and position influence subsequent fracture risk."},{"id":"a003-v8-17-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"TTV 用兩面的局部間距計算；弓形用中面相對參考面計算，因此厚度均勻的片仍可能彎曲。","textEn":"TTV measures local separation of both faces while bow describes the median surface; uniform thickness can coexist with curvature."}],"quiz":{"question":"評估「邊緣崩缺」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating classify edge chips?","options":["平均值相同就不必檢查片間分布。","邊緣缺口尺寸及位置共同影響後續破片風險。","材料移除量不會影響可用晶圓數。"],"optionsEn":["Equal averages eliminate the need to inspect wafer distributions.","Edge-chip size and position influence subsequent fracture risk.","Material removal cannot affect usable wafer count."],"answer":1,"explanation":"邊緣缺口尺寸及位置共同影響後續破片風險。 TTV 用兩面的局部間距計算；弓形用中面相對參考面計算，因此厚度均勻的片仍可能彎曲。","explanationEn":"Edge-chip size and position influence subsequent fracture risk. TTV measures local separation of both faces while bow describes the median surface; uniform thickness can coexist with curvature."}},{"id":"a003-v8-18","order":6,"sequence":18,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-sumco","v8a-wafer"],"prerequisiteIds":["a003-v8-17"],"title":"量測重複性","titleEn":"Check measurement repeatability","objective":"完成「量測重複性」的工程驗收單，把切縫、TTV、次表面損傷中的相關限制連到可觀察證據。","objectiveEn":"Complete a engineering acceptance sheet for check measurement repeatability, connecting relevant limits in kerf, ttv and subsurface damage to observable evidence.","instruction":"本步問題：量測重複性。整合本步及本階段先前證據；提出兩項彼此不同的接受條件；再列一個會讓你暫緩放行的結果及下一個確認動作。判讀依據：重新放片的變異應先與片間差異分開。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Check measurement repeatability. Combine this step with earlier stage evidence; propose two independent acceptance criteria; name one hold condition and the next confirming action. Interpretation: Repositioning variation must be separated from wafer variation. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「重新放片的變異應先與片間差異分開。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Repositioning variation must be separated from wafer variation. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：平均值相同就不必檢查片間分布。 應回到「量測重複性」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Equal averages eliminate the need to inspect wafer distributions. Revisit assumptions and sampling for check measurement repeatability and add discriminating evidence.","check":"交付「量測重複性」工程驗收單：驗收單需有原理、兩項證據、保留疑問及前後模組交接。","checkEn":"Submit the engineering acceptance sheet for check measurement repeatability: The sheet needs the principle, two evidence items, open questions and module handoff.","knowledge":[{"id":"a003-v8-18-k1","title":"量測重複性的原理","titleEn":"Check measurement repeatability principle","text":"重新放片的變異應先與片間差異分開。","textEn":"Repositioning variation must be separated from wafer variation."},{"id":"a003-v8-18-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"TTV 用兩面的局部間距計算；弓形用中面相對參考面計算，因此厚度均勻的片仍可能彎曲。","textEn":"TTV measures local separation of both faces while bow describes the median surface; uniform thickness can coexist with curvature."}],"quiz":{"question":"評估「量測重複性」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating check measurement repeatability?","options":["平均值相同就不必檢查片間分布。","材料移除量不會影響可用晶圓數。","重新放片的變異應先與片間差異分開。"],"optionsEn":["Equal averages eliminate the need to inspect wafer distributions.","Material removal cannot affect usable wafer count.","Repositioning variation must be separated from wafer variation."],"answer":2,"explanation":"重新放片的變異應先與片間差異分開。 TTV 用兩面的局部間距計算；弓形用中面相對參考面計算，因此厚度均勻的片仍可能彎曲。","explanationEn":"Repositioning variation must be separated from wafer variation. TTV measures local separation of both faces while bow describes the median surface; uniform thickness can coexist with curvature."}}]},{"id":"a003-stage04","order":4,"title":"良率與後段交接","titleEn":"Yield and downstream handoff","description":"在「良率與後段交接」建立六項互補證據，逐一檢查材料、幾何、物理機制與適用限制。","descriptionEn":"Build six complementary evidence items for yield and downstream handoff, checking materials, geometry, mechanisms and validity limits.","steps":[{"id":"a003-v8-19","order":1,"sequence":19,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-sumco","v8a-wafer"],"prerequisiteIds":["a003-v8-18"],"title":"材料利用率","titleEn":"Compute material utilization","objective":"完成「材料利用率」的因果圖，把切縫、TTV、次表面損傷中的相關限制連到可觀察證據。","objectiveEn":"Complete a causal diagram for compute material utilization, connecting relevant limits in kerf, ttv and subsurface damage to observable evidence.","instruction":"本步問題：材料利用率。畫一張含作用前後狀態的原創圖；以箭頭標出本步原理中的因果關係；圈出一項仍需量測的未知量。判讀依據：提高片數若同時增加報廢，未必提高有效矽利用率。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Compute material utilization. Draw an original before/after diagram; mark the causal relationship in this step; circle one quantity still requiring measurement. Interpretation: More slices may not improve usable silicon yield if rejects increase. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「提高片數若同時增加報廢，未必提高有效矽利用率。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: More slices may not improve usable silicon yield if rejects increase. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：局部截面合格就能取代整片量測。 應回到「材料利用率」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: One acceptable section replaces full-wafer measurement. Revisit assumptions and sampling for compute material utilization and add discriminating evidence.","check":"交付「材料利用率」因果圖：圖中要有邊界、輸入、輸出與一項不能僅由圖決定的量。","checkEn":"Submit the causal diagram for compute material utilization: Show boundaries, inputs, outputs and one quantity that the diagram alone cannot determine.","knowledge":[{"id":"a003-v8-19-k1","title":"材料利用率的原理","titleEn":"Compute material utilization principle","text":"提高片數若同時增加報廢，未必提高有效矽利用率。","textEn":"More slices may not improve usable silicon yield if rejects increase."},{"id":"a003-v8-19-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"切片端減少切縫的收益，若被後段新增的損傷移除量抵銷，整體矽利用率可能沒有增加。","textEn":"A smaller kerf may not improve overall silicon utilization if it requires more downstream damage removal."}],"quiz":{"question":"評估「材料利用率」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating compute material utilization?","options":["提高片數若同時增加報廢，未必提高有效矽利用率。","局部截面合格就能取代整片量測。","所有表面缺陷都能由後段拋光無代價消除。"],"optionsEn":["More slices may not improve usable silicon yield if rejects increase.","One acceptable section replaces full-wafer measurement.","All surface defects can be removed by later polishing without cost."],"answer":0,"explanation":"提高片數若同時增加報廢，未必提高有效矽利用率。 切片端減少切縫的收益，若被後段新增的損傷移除量抵銷，整體矽利用率可能沒有增加。","explanationEn":"More slices may not improve usable silicon yield if rejects increase. A smaller kerf may not improve overall silicon utilization if it requires more downstream damage removal."}},{"id":"a003-v8-20","order":2,"sequence":20,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-sumco","v8a-wafer"],"prerequisiteIds":["a003-v8-19"],"title":"線耗追蹤","titleEn":"Track wire consumption","objective":"完成「線耗追蹤」的對照表，把切縫、TTV、次表面損傷中的相關限制連到可觀察證據。","objectiveEn":"Complete a controlled comparison for track wire consumption, connecting relevant limits in kerf, ttv and subsurface damage to observable evidence.","instruction":"本步問題：線耗追蹤。建立兩個只改一項條件的假想案例；分開記錄可觀察差異與推測原因；說明如何用本步原理區分兩者。判讀依據：線耗量需按合格片數正規化。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Track wire consumption. Create two hypothetical cases differing in one condition; separate observations from proposed causes; use this step’s principle to distinguish them. Interpretation: Wire consumption should be normalized by accepted wafers. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「線耗量需按合格片數正規化。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Wire consumption should be normalized by accepted wafers. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：只要每批總線耗下降，即使合格片數下降更多，也可判定單位合格片的線耗改善。 應回到「線耗追蹤」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Lower total wire use per batch proves better wire use per accepted wafer even if accepted output falls by a larger fraction. Revisit assumptions and sampling for track wire consumption and add discriminating evidence.","check":"交付「線耗追蹤」對照表：交出兩案例、固定條件、預期差異及一項可能混淆因素。","checkEn":"Submit the controlled comparison for track wire consumption: Submit both cases, fixed conditions, predicted difference and one confounder.","knowledge":[{"id":"a003-v8-20-k1","title":"線耗追蹤的原理","titleEn":"Track wire consumption principle","text":"線耗量需按合格片數正規化。","textEn":"Wire consumption should be normalized by accepted wafers."},{"id":"a003-v8-20-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"切片端減少切縫的收益，若被後段新增的損傷移除量抵銷，整體矽利用率可能沒有增加。","textEn":"A smaller kerf may not improve overall silicon utilization if it requires more downstream damage removal."}],"quiz":{"question":"評估「線耗追蹤」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating track wire consumption?","options":["只要每批總線耗下降，即使合格片數下降更多，也可判定單位合格片的線耗改善。","線耗量需按合格片數正規化。","比較線耗時只需計入切出的片數，不必區分後續判退與合格片。"],"optionsEn":["Lower total wire use per batch proves better wire use per accepted wafer even if accepted output falls by a larger fraction.","Wire consumption should be normalized by accepted wafers.","Wire-use comparisons need only the number of sliced wafers, without separating subsequent rejects from accepted wafers."],"answer":1,"explanation":"線耗量需按合格片數正規化。 切片端減少切縫的收益，若被後段新增的損傷移除量抵銷，整體矽利用率可能沒有增加。","explanationEn":"Wire consumption should be normalized by accepted wafers. A smaller kerf may not improve overall silicon utilization if it requires more downstream damage removal."}},{"id":"a003-v8-21","order":3,"sequence":21,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-sumco","v8a-wafer"],"prerequisiteIds":["a003-v8-20"],"title":"切片序列圖","titleEn":"Plot slice-order trends","objective":"完成「切片序列圖」的敏感度草圖，把切縫、TTV、次表面損傷中的相關限制連到可觀察證據。","objectiveEn":"Complete a sensitivity sketch for plot slice-order trends, connecting relevant limits in kerf, ttv and subsurface damage to observable evidence.","instruction":"本步問題：切片序列圖。選出本步的一項輸入及一項輸出；以自訂低、中、高三點畫趨勢；逐點標註假設，並寫出趨勢可能失效的條件。判讀依據：連續片的週期性厚度誤差可提示導輪相關因素。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Plot slice-order trends. Select one input and output for this step; sketch a hypothetical low/mid/high trend; label assumptions and state when the trend may fail. Interpretation: Periodic slice-thickness errors can suggest guide-related causes. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「連續片的週期性厚度誤差可提示導輪相關因素。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Periodic slice-thickness errors can suggest guide-related causes. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：局部截面合格就能取代整片量測。 應回到「切片序列圖」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: One acceptable section replaces full-wafer measurement. Revisit assumptions and sampling for plot slice-order trends and add discriminating evidence.","check":"交付「切片序列圖」敏感度草圖：圖須有變數、單位或無因次定義、三個假設點及適用範圍。","checkEn":"Submit the sensitivity sketch for plot slice-order trends: Include variables, units or dimensionless definitions, three hypothetical points and validity limits.","knowledge":[{"id":"a003-v8-21-k1","title":"切片序列圖的原理","titleEn":"Plot slice-order trends principle","text":"連續片的週期性厚度誤差可提示導輪相關因素。","textEn":"Periodic slice-thickness errors can suggest guide-related causes."},{"id":"a003-v8-21-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"切片端減少切縫的收益，若被後段新增的損傷移除量抵銷，整體矽利用率可能沒有增加。","textEn":"A smaller kerf may not improve overall silicon utilization if it requires more downstream damage removal."}],"quiz":{"question":"評估「切片序列圖」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating plot slice-order trends?","options":["局部截面合格就能取代整片量測。","所有表面缺陷都能由後段拋光無代價消除。","連續片的週期性厚度誤差可提示導輪相關因素。"],"optionsEn":["One acceptable section replaces full-wafer measurement.","All surface defects can be removed by later polishing without cost.","Periodic slice-thickness errors can suggest guide-related causes."],"answer":2,"explanation":"連續片的週期性厚度誤差可提示導輪相關因素。 切片端減少切縫的收益，若被後段新增的損傷移除量抵銷，整體矽利用率可能沒有增加。","explanationEn":"Periodic slice-thickness errors can suggest guide-related causes. A smaller kerf may not improve overall silicon utilization if it requires more downstream damage removal."}},{"id":"a003-v8-22","order":4,"sequence":22,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-sumco","v8a-wafer"],"prerequisiteIds":["a003-v8-21"],"title":"移除留量交接","titleEn":"Transfer removal allowance","objective":"完成「移除留量交接」的故障判別表，把切縫、TTV、次表面損傷中的相關限制連到可觀察證據。","objectiveEn":"Complete a fault-discrimination table for transfer removal allowance, connecting relevant limits in kerf, ttv and subsurface damage to observable evidence.","instruction":"本步問題：移除留量交接。假設本步預期結果未出現；提出兩個不同機制；為各機制選一個能支持或否定的觀察，避免只重複同一量測。判讀依據：研磨端需要最深損傷估計而不只是平均厚度。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Transfer removal allowance. Assume the expected result fails; propose two distinct mechanisms; choose an observation that supports or rejects each rather than repeating one measurement. Interpretation: Lapping needs estimated deepest damage, not just mean thickness. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「研磨端需要最深損傷估計而不只是平均厚度。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Lapping needs estimated deepest damage, not just mean thickness. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：局部截面合格就能取代整片量測。 應回到「移除留量交接」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: One acceptable section replaces full-wafer measurement. Revisit assumptions and sampling for transfer removal allowance and add discriminating evidence.","check":"交付「移除留量交接」故障判別表：至少列出兩個假說、各自的辨別證據及先檢查順序。","checkEn":"Submit the fault-discrimination table for transfer removal allowance: List two hypotheses, discriminating evidence for each and a check order.","knowledge":[{"id":"a003-v8-22-k1","title":"移除留量交接的原理","titleEn":"Transfer removal allowance principle","text":"研磨端需要最深損傷估計而不只是平均厚度。","textEn":"Lapping needs estimated deepest damage, not just mean thickness."},{"id":"a003-v8-22-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"切片端減少切縫的收益，若被後段新增的損傷移除量抵銷，整體矽利用率可能沒有增加。","textEn":"A smaller kerf may not improve overall silicon utilization if it requires more downstream damage removal."}],"quiz":{"question":"評估「移除留量交接」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating transfer removal allowance?","options":["研磨端需要最深損傷估計而不只是平均厚度。","局部截面合格就能取代整片量測。","所有表面缺陷都能由後段拋光無代價消除。"],"optionsEn":["Lapping needs estimated deepest damage, not just mean thickness.","One acceptable section replaces full-wafer measurement.","All surface defects can be removed by later polishing without cost."],"answer":0,"explanation":"研磨端需要最深損傷估計而不只是平均厚度。 切片端減少切縫的收益，若被後段新增的損傷移除量抵銷，整體矽利用率可能沒有增加。","explanationEn":"Lapping needs estimated deepest damage, not just mean thickness. A smaller kerf may not improve overall silicon utilization if it requires more downstream damage removal."}},{"id":"a003-v8-23","order":5,"sequence":23,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-sumco","v8a-wafer"],"prerequisiteIds":["a003-v8-22"],"title":"盲樣重驗","titleEn":"Recheck blinded samples","objective":"完成「盲樣重驗」的量測規劃，把切縫、TTV、次表面損傷中的相關限制連到可觀察證據。","objectiveEn":"Complete a measurement plan for recheck blinded samples, connecting relevant limits in kerf, ttv and subsurface damage to observable evidence.","instruction":"本步問題：盲樣重驗。針對本步定義待測量及採樣位置；列出解析度、背景與重複性；設計一個見證或空白，並說明檢出限如何限制結論。判讀依據：對邊界片重驗須保留原片序與量測版本。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Recheck blinded samples. Define the measurand and sampling locations; list resolution, background and repeatability; design a witness or blank and explain detection-limit constraints. Interpretation: Boundary-sample retests need original slice identity and measurement version. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「對邊界片重驗須保留原片序與量測版本。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Boundary-sample retests need original slice identity and measurement version. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：局部截面合格就能取代整片量測。 應回到「盲樣重驗」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: One acceptable section replaces full-wafer measurement. Revisit assumptions and sampling for recheck blinded samples and add discriminating evidence.","check":"交付「盲樣重驗」量測規劃：提供採樣座標、量測單位、對照與不確定度來源。","checkEn":"Submit the measurement plan for recheck blinded samples: Provide sampling coordinates, units, controls and uncertainty sources.","knowledge":[{"id":"a003-v8-23-k1","title":"盲樣重驗的原理","titleEn":"Recheck blinded samples principle","text":"對邊界片重驗須保留原片序與量測版本。","textEn":"Boundary-sample retests need original slice identity and measurement version."},{"id":"a003-v8-23-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"切片端減少切縫的收益，若被後段新增的損傷移除量抵銷，整體矽利用率可能沒有增加。","textEn":"A smaller kerf may not improve overall silicon utilization if it requires more downstream damage removal."}],"quiz":{"question":"評估「盲樣重驗」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating recheck blinded samples?","options":["局部截面合格就能取代整片量測。","對邊界片重驗須保留原片序與量測版本。","所有表面缺陷都能由後段拋光無代價消除。"],"optionsEn":["One acceptable section replaces full-wafer measurement.","Boundary-sample retests need original slice identity and measurement version.","All surface defects can be removed by later polishing without cost."],"answer":1,"explanation":"對邊界片重驗須保留原片序與量測版本。 切片端減少切縫的收益，若被後段新增的損傷移除量抵銷，整體矽利用率可能沒有增加。","explanationEn":"Boundary-sample retests need original slice identity and measurement version. A smaller kerf may not improve overall silicon utilization if it requires more downstream damage removal."}},{"id":"a003-v8-24","order":6,"sequence":24,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-sumco","v8a-wafer"],"prerequisiteIds":["a003-v8-23"],"title":"切片批次放行","titleEn":"Release a slicing lot","objective":"完成「切片批次放行」的工程驗收單，把切縫、TTV、次表面損傷中的相關限制連到可觀察證據。","objectiveEn":"Complete a engineering acceptance sheet for release a slicing lot, connecting relevant limits in kerf, ttv and subsurface damage to observable evidence.","instruction":"本步問題：切片批次放行。整合本步及本階段先前證據；提出兩項彼此不同的接受條件；再列一個會讓你暫緩放行的結果及下一個確認動作。判讀依據：厚度、損傷、邊緣與追溯證據須同時交付。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Release a slicing lot. Combine this step with earlier stage evidence; propose two independent acceptance criteria; name one hold condition and the next confirming action. Interpretation: Release requires thickness, damage, edge and traceability evidence together. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「厚度、損傷、邊緣與追溯證據須同時交付。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Release requires thickness, damage, edge and traceability evidence together. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：局部截面合格就能取代整片量測。 應回到「切片批次放行」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: One acceptable section replaces full-wafer measurement. Revisit assumptions and sampling for release a slicing lot and add discriminating evidence.","check":"交付「切片批次放行」工程驗收單：驗收單需有原理、兩項證據、保留疑問及前後模組交接。","checkEn":"Submit the engineering acceptance sheet for release a slicing lot: The sheet needs the principle, two evidence items, open questions and module handoff.","knowledge":[{"id":"a003-v8-24-k1","title":"切片批次放行的原理","titleEn":"Release a slicing lot principle","text":"厚度、損傷、邊緣與追溯證據須同時交付。","textEn":"Release requires thickness, damage, edge and traceability evidence together."},{"id":"a003-v8-24-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"切片端減少切縫的收益，若被後段新增的損傷移除量抵銷，整體矽利用率可能沒有增加。","textEn":"A smaller kerf may not improve overall silicon utilization if it requires more downstream damage removal."}],"quiz":{"question":"評估「切片批次放行」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating release a slicing lot?","options":["局部截面合格就能取代整片量測。","所有表面缺陷都能由後段拋光無代價消除。","厚度、損傷、邊緣與追溯證據須同時交付。"],"optionsEn":["One acceptable section replaces full-wafer measurement.","All surface defects can be removed by later polishing without cost.","Release requires thickness, damage, edge and traceability evidence together."],"answer":2,"explanation":"厚度、損傷、邊緣與追溯證據須同時交付。 切片端減少切縫的收益，若被後段新增的損傷移除量抵銷，整體矽利用率可能沒有增加。","explanationEn":"Release requires thickness, damage, edge and traceability evidence together. A smaller kerf may not improve overall silicon utilization if it requires more downstream damage removal."}}]}],"subcategory":"substrate","subcategoryTitle":"晶圓與基板","subcategoryTitleEn":"Wafers and substrates"}};
